package javaclassparser

import (
	"strings"

	"github.com/yaklang/javajive/classparser/decompiler/core/class_context"
	"github.com/yaklang/javajive/internal/workbudget"
)

// A version/constant-pool proof does not establish that declaration names can
// be regenerated by the native Java8 source protocol. Check every emitted ABI
// name, including public fields that need no accessor packet. This is separate
// from the formatter: repairing a spelling grants no original-symbol identity.
func nativeDeclarationNamesCompatible(obj *ClassObject, work *workbudget.Budget) bool {
	if obj == nil {
		return false
	}
	check := func(name string) bool {
		return nativeProofWork(work, int64(len(name))+1) && class_context.PreservesJava8Identifier(name)
	}
	name := obj.GetClassName()
	for {
		part, rest, more := strings.Cut(name, "/")
		if !check(part) {
			return false
		}
		if !more {
			break
		}
		name = rest
	}
	for tableIndex, declarations := range [][]*MemberInfo{obj.Fields, obj.Methods} {
		for _, member := range declarations {
			if member == nil || !nativeProofWork(work, 1) {
				return false
			}
			name, known := sourceBridgeUTF8(obj, member.NameIndex)
			if !known {
				return false
			}
			if name == "<init>" || name == "<clinit>" {
				// Only methods can have these JVM-only initialization names.
				if tableIndex != 1 {
					return false
				}
				continue
			}
			if !check(name) {
				return false
			}
		}
	}
	return true
}
